## 6. 테스트 커버리지 개선

### 6.1 단위 테스트 도입

#### 현재 문제점

1. **테스트 코드 부재**

#### 권장사항

```javascript
// __tests__/utils/common.test.js
import { describe, it, expect } from 'vitest'
import { formatYmd, formatNumber, isSuccess } from '@/utils/common'

describe('formatYmd', () => {
    it('날짜를 YYYY-MM-DD 형식으로 포맷한다', () => {
        const date = new Date('2024-01-15')
        expect(formatYmd(date)).toBe('2024-01-15')
    })

    it('빈 값은 빈 문자열을 반환한다', () => {
        expect(formatYmd(null)).toBe('')
        expect(formatYmd(undefined)).toBe('')
    })
})

describe('isSuccess', () => {
    it('code 가 200 일 때 true 를 반환한다', () => {
        const response = { data: { code: '200' } }
        expect(isSuccess(response)).toBe(true)
    })

    it('success 가 true 일 때 true 를 반환한다', () => {
        const response = { data: { success: true } }
        expect(isSuccess(response)).toBe(true)
    })
})
```

