import { defineStore } from 'pinia'
import { ref } from 'vue'

export const useConfirmStore = defineStore('confirm', () => {
	const visible = ref(false)
	const text = ref('')

	let onConfirm = null
	let onCancel = null
	let confirmArgs = null
	let cancelArgs = null

	const open = ({ message, confirm, cancel, confirmArgs: cArgs, cancelArgs: caArgs }) => {
		text.value = message || ''
		onConfirm = typeof confirm === 'function' ? confirm : null
		onCancel = typeof cancel === 'function' ? cancel : null
		confirmArgs = cArgs
		cancelArgs = caArgs
		visible.value = true
	}

	const confirmAction = () => {
		visible.value = false
		const fn = onConfirm
		const args = confirmArgs
		onConfirm = null
		onCancel = null
		confirmArgs = null
		cancelArgs = null
		if (fn) fn(...(Array.isArray(args) ? args : [args]))
	}

	const cancelAction = () => {
		visible.value = false
		const fn = onCancel
		const args = cancelArgs
		onConfirm = null
		onCancel = null
		confirmArgs = null
		cancelArgs = null
		if (fn) fn(...(Array.isArray(args) ? args : [args]))
	}

	return { visible, text, open, confirmAction, cancelAction }
})
