 * @param {string} userId - 특정 사용자만 삭제하고 싶을 경우 (없으면 전체 삭제)
 */
export const clearAppListCache = (userId, serviceMenu) => {
	const storageKey = STORAGE_KEYS.APP_LIST
	SERVICE_MENU = serviceMenu
	if (userId) {
		// 특정 키만 삭제
		const cacheKey = `${SERVICE_MENU}_${userId}`
		const cached = commonStorage.get(storageKey) || {}
		delete cached[cacheKey]
		commonStorage.setItem(storageKey, cached)
	} else {
		// 전체 삭제
		commonStorage.remove(storageKey)
	}
}

