    const cacheKey = mode ? `workTools_${userId}` : `all_${userId}`;

    try {
		if(appInfos?.appId == appId && appInfos._raw && !refresh){
			return appInfos._raw
		}
        // 캐시에서 앱 리스트 가져오기
