			}else{
				appList = await fetchAndCacheAppList(serviceMenu, userId, storageKey, cacheKey);
			}
        }

        // 앱 정보 찾기
        let appInfo = findAppInfo(appList, appId, mode, serviceMenu);
		// 캐시(사이드메뉴 상위 목록)에 없으면 전체 목록으로 재조회
		if (!appInfo) {
			appList = await fetchAndCacheAppList(serviceMenu, userId, storageKey, cacheKey);
			appInfo = findAppInfo(appList, appId, mode, serviceMenu);
		}
		if (!appInfo) return appInfo;
		writeOpenApp(appInfo)
        if(mode === "simple"){
            // ocr, stt.. 으로 진입 시에는 호출하지 않음
            try {
                clearOpenAppDoc()
                const res = await inf.app.getUsed.call(appId, {
                    user_id : userId
                })
                const fileInfos = res?.data?.body?.knowledgeDetail_info
                writeOpenAppDoc({
                    ...fileInfos, 
                    appId : res?.data?.body?.app_id
                })
            } catch (error) {
                console.log("writeOpenApp", error)
            }
        }
        return appInfo;
    } catch (e) {
        return {};
    }
};

